<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {session,logout,roles,alert,isDemo} from './api';import Icon from './components/Icon.vue'
const route=useRoute();const mobile=ref(false)
const nav=computed(()=>[{to:'/',label:'Resumen',icon:'dashboard'},{to:'/orders',label:session.user?.role==='MECHANIC'?'Mis trabajos':'Órdenes de servicio',icon:'orders'},...(session.user?.role==='ADMIN'?[{to:'/customers',label:'Clientes',icon:'users'}]:[]),{to:'/vehicles',label:'Vehículos',icon:'car'},...(session.user?.role!=='CLIENT'?[{to:'/inventory',label:'Inventario',icon:'box'}]:[]),...(session.user?.role==='ADMIN'?[{to:'/employees',label:'Equipo',icon:'wrench'},{to:'/reports',label:'Reportes',icon:'chart'},{to:'/audit',label:'Auditoría',icon:'shield'}]:[])])
const section=computed(()=>nav.value.find(n=>n.to==='/'?route.path==='/':route.path.startsWith(n.to))?.label||'Mi cuenta')
</script>
<template><div v-if="session.loading" class="loading-screen">Preparando el taller…</div><template v-else-if="session.user&&!['/forgot','/reset','/register'].includes(route.path)"><aside class="sidebar" :class="{open:mobile}"><RouterLink class="brand" to="/"><span class="brand-icon"><Icon name="wrench" :size="25"/></span><span>Taller<span class="brand-light">Meco</span><small>GESTIÓN DEL TALLER</small></span></RouterLink><p class="nav-caption">ESPACIO DE TRABAJO</p><nav><RouterLink v-for="item in nav" :key="item.to" :to="item.to" :class="{selected:item.to==='/'?route.path==='/':route.path.startsWith(item.to)}" @click="mobile=false"><Icon :name="item.icon"/>{{item.label}}<Icon v-if="item.to===route.path" name="chevron" :size="15" class="nav-chevron"/></RouterLink></nav><div class="sidebar-bottom"><div class="local-note"><span class="status-dot"></span>Tu taller, en orden.<small>Todo lo importante, en un lugar.</small></div><RouterLink to="/account" class="profile-link"><span class="avatar">{{session.user.name?.slice(0,2).toUpperCase()}}</span><span><strong>{{session.user.name}}</strong><small>{{roles[session.user.role]}}</small></span></RouterLink><button class="signout" @click="logout"><Icon name="logout" :size="17"/>Cerrar sesión</button></div></aside><button v-if="mobile" class="sidebar-overlay" aria-label="Cerrar menú" @click="mobile=false"></button><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-toggle" aria-label="Abrir menú" @click="mobile=!mobile"><Icon name="menu"/></button><span>Mi taller</span><Icon name="chevron" :size="14"/><strong>{{section}}</strong></div><div class="topbar-right"><span class="today">{{new Date().toLocaleDateString('es-MX',{day:'numeric',month:'long',year:'numeric'})}}</span><span class="role-pill">{{roles[session.user.role]}}</span></div></header><div v-if="isDemo" class="demo-strip"><strong>PROTOTIPO LOCAL</strong> Datos de ejemplo guardados en este navegador. Sin conexión al backend ni autenticación real.</div><main id="main-content"><RouterView :key="route.path"/></main><footer class="app-footer"><span>TallerMeco</span><span>Hecho para mantener tu taller en movimiento.</span></footer></div></template><RouterView v-else :key="route.path"/><div v-if="alert.message" class="toast" :class="alert.type" role="status"><Icon :name="alert.type==='success'?'check':'shield'"/>{{alert.message}}<button class="icon-button" aria-label="Cerrar notificación" @click="alert.message=''"><Icon name="close" :size="16"/></button></div></template>
